"""Decode caliper-docgen's interned `extract --json` output.

rows.py rows <json> <Component>...      the listed rows (props + notableInherited), with each row's parent
rows.py counts <json> <Component>...    row counts
rows.py summary <json>                  components, median rows, total rows, layer names
rows.py diff <expanded.json> <listed.json> [--top N]
    main-props differential: every member of the expanded view (collapse none) that has no parent, or whose parent
    source reaches with at most 30 members and is not ambient (@types/react, node_modules/react, @react-types/shared
    dom.d.ts), must be a listed row of the listed run. Prints violations and the most common names the listed run
    leaves out of larger or ambient sources.
"""
import collections
import json
import statistics
import sys


def load(path):
    return json.load(open(path))


def rows(d, c):
    """name -> prop of the component's listed rows."""
    out = {}
    for set_id in c.get('props') or []:
        for name, pid in d['propSets'][set_id].items():
            out[name] = d['props'][pid]
    for name, pid in (c.get('notableInherited') or {}).items():
        out[name] = d['props'][pid]
    return out


def layer_names(d, c):
    n = 0
    for layer in c.get('inheritance') or []:
        m = layer.get('members')
        if m:
            n += len(d['nameLists'][m])
    return n


def ambient(file):
    if '/@types/react/' in file or '/node_modules/react/' in file:
        return True
    tail = file.rsplit('/@react-types/shared/src/', 1)
    return len(tail) == 2 and tail[1] in ('dom.d.ts', 'dom.d.mts', 'dom.d.cts')


def required_rows(d, c):
    """Members of the expanded view the main-props rule must list."""
    r = rows(d, c)
    size = collections.Counter((p['parent']['name'], p['parent']['fileName']) for p in r.values() if p.get('parent'))
    need = set()
    for name, p in r.items():
        parents = ([p['parent']] if p.get('parent') else []) + (p.get('declarations') or [])
        if any(ambient(x['fileName']) for x in parents):
            continue
        if not p.get('parent') or size[(p['parent']['name'], p['parent']['fileName'])] <= 30:
            need.add(name)
    return need, r


def main():
    mode = sys.argv[1]
    if mode in ('rows', 'counts'):
        d = load(sys.argv[2])
        for comp in sys.argv[3:]:
            c = d['components'].get(comp)
            if c is None:
                print(comp, 'MISSING')
                continue
            r = rows(d, c)
            if mode == 'counts':
                print(comp, len(r))
            else:
                print(comp, len(r), ', '.join(sorted(r)))
    elif mode == 'summary':
        d = load(sys.argv[2])
        counts = [len(rows(d, c)) for c in d['components'].values()]
        layers = sum(layer_names(d, c) for c in d['components'].values())
        print(f"components={len(counts)} median={statistics.median(counts) if counts else 0} total={sum(counts)} layer_names={layers}")
    elif mode == 'diff':
        expanded, listed = load(sys.argv[2]), load(sys.argv[3])
        top = int(sys.argv[5]) if len(sys.argv) > 5 else 20
        violations, hidden, checked = [], collections.Counter(), 0
        for key, c in expanded['components'].items():
            lc = listed['components'].get(key)
            if lc is None:
                continue
            need, r = required_rows(expanded, c)
            have = set(rows(listed, lc))
            checked += 1
            for name in sorted(need - have):
                violations.append(f"{key}: {name}")
            for name in set(r) - have - need:
                hidden[name] += 1
        print(f"components={checked} violations={len(violations)}")
        for v in violations[:30]:
            print('  VIOLATION', v)
        print('most common hidden:', ', '.join(f"{n} ({k})" for n, k in hidden.most_common(top)))


main()
