import * as React from 'react';
import { useEffect } from 'react';
import { FakeButton, type Big40Props, type Huge210Props } from 'fake-lib';
import type { HugeLocalProps } from './huge-local';

type Div = React.HTMLAttributes<HTMLDivElement>;

// (i) DOM props read in a handler (title), useEffect (tabIndex), template (lang), nested closure (dir); control: direct (hidden).
export interface P1Props extends Div { own1?: string }
export function P1Closures(props: P1Props) {
  const onClick = () => console.log(props.title);
  useEffect(() => { console.log(props.tabIndex); }, []);
  function inner() { return props.dir; }
  return <div onClick={onClick} data-x={inner()} {...props}>{`${props.lang}`}{String(props.hidden)}</div>;
}

// (ii-a) rest spread onto a child COMPONENT that destructures title and onFocus.
function Inner({ title, onFocus }: { title?: string; onFocus?: React.FocusEventHandler }) {
  return <span title={title} onFocus={onFocus} />;
}
export interface P2Props extends Div { own2?: string }
export function P2ToComponent({ own2, ...rest }: P2Props) {
  return <Inner {...rest} />;
}
// (ii-b) rest spread onto a DOM tag: nothing promoted.
export function P2ToDom({ own2, ...rest }: P2Props) {
  return <div {...rest} />;
}
// (ii-c) rest spread onto a dependency component whose props are Big40 & button attributes.
export interface P2cProps extends Big40Props, React.ButtonHTMLAttributes<HTMLButtonElement> { own2c?: string }
export function P2ToDepComponent({ own2c, ...rest }: P2cProps) {
  return <FakeButton {...rest} />;
}

// (iii) bracket access (title) and alias (const p = props; p.lang).
export interface P3Props extends Div { own3?: string }
export function P3Bracket(props: P3Props) {
  const p = props;
  return <div data-a={props['title']} data-b={p.lang} {...props} />;
}

// (v) a >200-member project source: body reads loc5.
export interface P5Props extends HugeLocalProps, Div { own5?: string }
export function P5HugeLocal(props: P5Props) {
  return <div data-x={props.loc5} />;
}
// (v-b) a >200-member dependency source: body reads big5.
export interface P5bProps extends Huge210Props { own5b?: string }
export function P5bHugeDep(props: P5bProps) {
  return <div data-x={props.big5} />;
}

// (vi) 40 API props in ONE dependency interface: extends, bare alias, Partial, Pick.
export interface P6Props extends Big40Props { own6?: string }
export function P6Extends(props: P6Props) { return <div>{props.own6}</div>; }
export function P6Bare(props: Big40Props) { return <div>{props.api0}</div>; }
export function P6Partial(props: Partial<Big40Props> & { own6p?: string }) { return <div>{props.own6p}</div>; }
export function P6Required(props: Required<Big40Props>) { return <div />; }
export function P6Omit(props: Omit<Big40Props, 'api0'>) { return <div />; }

// (vii) discriminated union & DOM attributes; body reads title in one branch.
export type P7Props = ({ kind: 'a'; alpha: string } | { kind: 'b'; beta: number }) & Div;
export function P7Union(props: P7Props) {
  if (props.kind === 'a') return <div title={props.title}>{props.alpha}</div>;
  return <div {...props} />;
}

// (viii) a wrapper renaming props: label -> title, press -> onClick, and a renamed DOM destructure.
export interface P8Props extends Div { label?: string; press?: () => void }
export function P8Rename({ label, press, lang: language, ...rest }: P8Props) {
  return <button title={label} onClick={press} data-l={language} {...rest} />;
}

// forwardRef + memo wrapper reading one DOM prop.
export const P9Forward = React.memo(React.forwardRef<HTMLDivElement, P1Props>(function P9(props, ref) {
  return <div ref={ref} title={props.title} {...props} />;
}));

// hook-driven: props handed to a hook.
function useThing(p: P1Props) { return { ...p }; }
export function P10Hook(props: P1Props) {
  const r = useThing(props);
  return <div {...r} />;
}

