"""show.py: rows and layers per probe component, per binary and lane."""
import json
import re

NAMES = ['title', 'tabIndex', 'lang', 'dir', 'hidden', 'onFocus', 'onClick', 'loc5', 'big5', 'api0', 'api39', 'alpha', 'beta', 'kind', 'label', 'press']


def rows(d, c):
    o = {}
    for s in c.get('props') or []:
        for n, pid in d['propSets'][s].items():
            o[n] = d['props'][pid]
    for n, pid in (c.get('notableInherited') or {}).items():
        o[n] = d['props'][pid]
    return o


runs = {f'{b}/{l}': json.load(open(f'out.{b}.{l}.json')) for b in ('main', 'pr') for l in ('checker', 'structural')}
names = sorted(set().union(*(r['components'] for r in runs.values())))
for n in names:
    print(f'== {n}')
    for tag, d in runs.items():
        c = d['components'].get(n)
        if c is None:
            print(f'   {tag}: MISSING')
            continue
        r = rows(d, c)
        own = sorted(k for k in r if re.match(r'own|loc\d|big\d|api\d', k) is None)
        cnt = lambda pre: sum(1 for k in r if re.fullmatch(pre + r'\d+', k))
        lay = [(l['typeName'], l.get('totalProps'), len(d['nameLists'][l['members']]) if l.get('members') else 0) for l in c.get('inheritance') or []]
        print(f'   {tag}: rows {len(r)} api* {cnt("api")} big* {cnt("big")} loc* {cnt("loc")} | named rows {own} | probes '
              f'{[k for k in NAMES if k in r]} | layers {lay}')

