import json, collections, statistics
agg=collections.defaultdict(list)
for lib in ['fixtures','shadcn','antd','spectrum','mantine','chakra']:
    d=json.load(open(f'{lib}.patterns.json'))
    for sub,v in d.items():
        for pat,items in v['pat'].items():
            for it in items: agg[pat].append((sub,)+tuple(it))
for pat,items in sorted(agg.items()):
    libs=collections.Counter(i[0] for i in items)
    m=[i[2] for i in items]; p=[i[3] for i in items]
    grew=sum(1 for i in items if i[3]-i[2]>30); fell=sum(1 for i in items if i[2] and i[3]<0.1*i[2])
    hid=sum(i[6] for i in items)
    print(f"{pat}: {len(items)} comps; median {statistics.median(m)} -> {statistics.median(p)}; p95 {sorted(m)[int(.95*(len(m)-1))]} -> {sorted(p)[int(.95*(len(p)-1))]}; fell>90% {fell}; hidden names {hid}; libs {dict(libs)}")
    ex=sorted(items,key=lambda i:-i[6])
    picks=[ex[0]]+[i for i in ex if i[0]!=ex[0][0]][:1] if len(ex)>1 else ex[:1]
    for i in picks:
        print(f"   e.g. {i[0]}:{i[1]} rows {i[2]}->{i[3]} listed {i[4]} hidden({i[6]}) {i[5]}")
EOF
cat patterns.out | cut -c1-400

